<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render;

use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Rendering\Application\Service\DocumentAssetDumpService;
use Civi\Lughauth\Features\Document\Rendering\Application\Service\ThemeRenderService;
use Civi\Lughauth\Features\Document\Rendering\Domain\RenderedTemplate;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateRenderRequest;
use Civi\Lughauth\Features\Document\Rendering\Domain\Gateway\TemplateRenderGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateReadGateway;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionFilter;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionReadGateway;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableReadGateway;
use Civi\Lughauth\Features\Document\Snippet\Domain\Snippet;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetFilter;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetReadGateway;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\SnippetVersion;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionFilter;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionReadGateway;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

/**
 * Orchestrates the resolution and rendering of a stored template into a document.
 *
 * Responsibilities:
 *   1. Resolve the best-matching Template (tenant-specific first, then global).
 *   2. Select the best TemplateVersion using BCP 47 locale negotiation.
 *   3. Merge tenant-level TemplateVariable defaults with call-site overrides.
 *   4. Load Snippet partials (tenant-specific first, then global) with locale-aware version selection.
 *   5. Inject asset-directory path variables (theme_assets_path, template_assets_path, snippet_assets_path).
 *   6. Delegate the actual string substitution to the TemplateRenderGateway.
 *   7. Wrap the rendered content in the template's associated Theme, if one is set.
 */
class TemplateRenderUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateReadGateway $templateGateway,
        private readonly TemplateVersionReadGateway $versionGateway,
        private readonly TemplateVariableReadGateway $variableGateway,
        private readonly SnippetReadGateway $snippetGateway,
        private readonly SnippetVersionReadGateway $snippetVersionGateway,
        private readonly TemplateRenderGateway $renderGateway,
        private readonly ThemeRenderService $themeRenderer,
        private readonly DocumentAssetDumpService $assetDumpService,
    ) {
    }

    /**
     * Render the template identified by input code and channel.
     *
     * Returns null inside the result when no matching template or version exists.
     */
    public function render(TemplateRenderInput $input): TemplateRenderResult
    {
        $this->logDebug("Run Render usecase for Template");
        $span = $this->startSpan("Run Render usecase for Template");
        try {
            $template = $this->resolveTemplate($input->code(), $input->channel(), $input->tenant());
            if (null === $template) {
                $this->logDebug(
                    "No enabled template found: code='{code}' channel='{channel}' tenant='{tenant}'",
                    ['code' => $input->code(), 'channel' => $input->channel()->value, 'tenant' => $input->tenant()?->uid() ?? 'global']
                );
                return new TemplateRenderResult(null);
            }

            $version = $this->bestVersion($template, $input->locale());
            if (null === $version) {
                $this->logDebug("Template '{uid}' has no versions", ['uid' => $template->uid()]);
                return new TemplateRenderResult(null);
            }

            $variables = $this->mergeVariables($input->tenant(), $input->variables());
            $snippets  = $this->loadSnippets($input->tenant(), $input->locale());

            $variables = $this->injectAssetPaths($variables, $template, $input);

            $rendered = $this->renderGateway->render(new TemplateRenderRequest(
                htmlContent: $version->getContentHtml(),
                snippets: $snippets,
                variables: $variables,
                outputFormat: $input->outputFormat(),
                subject: $version->getSubject(),
                textContent: $version->getContentText(),
                assets: [],
            ));

            $rendered = $this->wrapWithTheme($rendered, $template, $input);

            return new TemplateRenderResult($rendered);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    // ---------------------------------------------------------------------------
    // Private — domain coordination logic
    // ---------------------------------------------------------------------------

    /**
     * Resolves the best-matching template:
     * tenant-specific (code + channel + tenant) first, then global (code + channel, no tenant).
     */
    private function resolveTemplate(string $code, TemplateChannelOptions $channel, ?TenantRef $tenant): ?Template
    {
        if (null !== $tenant) {
            $tenantMatch = $this->templateGateway->findOneByCodeAndTenant($code, $tenant);
            if ($tenantMatch !== null && $tenantMatch->isEnabled() && $tenantMatch->getChannel() === $channel) {
                return $tenantMatch;
            }
        }



        $globalMatch = $this->templateGateway->findOneByCodeAndTenant($code, null);
        if ($globalMatch !== null && $globalMatch->isEnabled() && $globalMatch->getChannel() === $channel) {
            return $globalMatch;
        }

        return null;
    }

    /**
     * Picks the best TemplateVersion using BCP 47 locale negotiation:
     * exact locale → language prefix → null (default) → any.
     */
    private function bestVersion(Template $template, ?string $locale): ?TemplateVersion
    {
        $slide    = $this->versionGateway->list((new TemplateVersionFilter())->withTemplate($template));
        $versions = $slide->values();

        if (empty($versions)) {
            return null;
        }

        usort($versions, static fn (TemplateVersion $a, TemplateVersion $b) => ($b->getVersion() ?? 0) <=> ($a->getVersion() ?? 0));

        if ($locale !== null) {
            foreach ($versions as $v) {
                if ($v->getLocale() === $locale) {
                    return $v;
                }
            }
            $lang = substr($locale, 0, 2);
            foreach ($versions as $v) {
                if ($v->getLocale() !== null && str_starts_with($v->getLocale(), $lang)) {
                    return $v;
                }
            }
        }

        foreach ($versions as $v) {
            if ($v->getLocale() === null) {
                return $v;
            }
        }

        return $versions[0];
    }

    /**
     * Builds the flat variable map: tenant defaults first, then call-site overrides on top.
     *
     * @param  array<string, string> $overrides
     * @return array<string, string>
     */
    private function mergeVariables(?TenantRef $tenant, array $overrides): array
    {
        $vars = [];

        if (null !== $tenant) {
            $slide = $this->variableGateway->list((new TemplateVariableFilter())->withTenant($tenant));
            foreach ($slide->values() as $variable) {
                if ($variable->isEnabled() && null !== $variable->getValue()) {
                    $vars[$variable->getCode()] = $variable->getValue();
                }
            }
        }

        return array_merge($vars, $overrides);
    }

    /**
     * Loads all enabled Snippet partials for the given tenant, indexed by code.
     * Tenant-specific snippets override global ones. Each snippet resolves its best
     * SnippetVersion using BCP 47 locale negotiation.
     *
     * Before returning, {{snippet_assets_path}} inside each snippet HTML is replaced with
     * the public URL of that specific snippet's asset directory, so each snippet author
     * can simply write {{snippet_assets_path}} without knowing their own code.
     *
     * @return array<string, string>
     */
    private function loadSnippets(?TenantRef $tenant, ?string $locale): array
    {
        $snippetMap = [];

        // Global snippets as baseline
        $global = $this->snippetGateway->list((new SnippetFilter())->withGlobal(true));
        foreach ($global->values() as $snippet) {
            if (!$snippet->isEnabled()) {
                continue;
            }
            $html = $this->bestSnippetVersion($snippet, $locale);
            if ($html !== null) {
                $code              = $snippet->getCode();
                $snippetMap[$code] = $this->prebakeSnippetAssetsPath($html, $snippet->uid() ?? '');
            }
        }

        // Tenant-specific snippets override globals
        if (null !== $tenant) {
            $tenantSlide = $this->snippetGateway->list((new SnippetFilter())->withTenant($tenant));
            foreach ($tenantSlide->values() as $snippet) {
                if (!$snippet->isEnabled()) {
                    continue;
                }
                $html = $this->bestSnippetVersion($snippet, $locale);
                if ($html !== null) {
                    $code              = $snippet->getCode();
                    $snippetMap[$code] = $this->prebakeSnippetAssetsPath($html, $snippet->uid() ?? '');
                }
            }
        }

        return $snippetMap;
    }

    /**
     * Replaces {{snippet_assets_path}} and {{{snippet_assets_path}}} in a snippet's
     * HTML with the actual public URL for that snippet's asset directory.
     * Done before the HTML becomes a Handlebars partial so each snippet resolves its
     * own path without any context gymnastics.
     */
    private function prebakeSnippetAssetsPath(string $html, string $uid): string
    {
        if ($uid === '') {
            return $html;
        }
        $path = $this->assetDumpService->snippetAssetsPath($uid);
        $html = str_replace('{{{snippet_assets_path}}}', $path, $html);
        $html = str_replace('{{snippet_assets_path}}', $path, $html);
        return $html;
    }

    private function bestSnippetVersion(Snippet $snippet, ?string $locale): ?string
    {
        $versions = $this->snippetVersionGateway
            ->list((new SnippetVersionFilter())->withSnippet(new SnippetRef($snippet->uid() ?? '')))
            ->values();

        if (empty($versions)) {
            return null;
        }

        usort($versions, static fn (SnippetVersion $a, SnippetVersion $b) => ($b->getVersion() ?? 0) <=> ($a->getVersion() ?? 0));

        if ($locale !== null) {
            foreach ($versions as $v) {
                if ($v->getLocale() === $locale) {
                    return $v->getContentHtml();
                }
            }
            $lang = substr($locale, 0, 2);
            foreach ($versions as $v) {
                if ($v->getLocale() !== null && str_starts_with($v->getLocale(), $lang)) {
                    return $v->getContentHtml();
                }
            }
        }

        foreach ($versions as $v) {
            if ($v->getLocale() === null) {
                return $v->getContentHtml();
            }
        }

        return $versions[0]->getContentHtml();
    }

    /**
     * Injects asset-directory path variables into the variable map:
     *   - template_assets_path  → public URL of this template's asset directory
     *   - theme_assets_path     → public URL of the associated theme's asset directory
     *                             (empty string when no theme is declared)
     *
     * snippet_assets_path is intentionally NOT included here: it is pre-baked into each
     * snippet's HTML string before it becomes a Handlebars partial (see prebakeSnippetAssetsPath).
     * That way {{snippet_assets_path}} inside a snippet resolves to that snippet's own path
     * without any per-snippet context injection.
     *
     * Call-site variables always take precedence over the injected values.
     *
     * @param  array<string, string> $variables Already-merged variable map
     * @return array<string, string>
     */
    private function injectAssetPaths(
        array $variables,
        Template $template,
        TemplateRenderInput $input,
    ): array {
        $templateAssetsPath = $this->assetDumpService->templateAssetsPath(
            $template->uid() ?? '',
            $input->tenant()?->uid(),
        );

        $themeAssetsPath = '';
        $themeName       = $template->getTheme();
        if ($themeName !== null && $themeName !== '') {
            $themeAssetsPath = $this->themeRenderer->resolveThemeAssetsPath($themeName, $input->tenant()) ?? '';
        }

        return array_merge([
            'template_assets_path' => $templateAssetsPath,
            'theme_assets_path'    => $themeAssetsPath,
        ], $variables);
    }

    /**
     * If the template declares a theme, wrap the rendered content in the corresponding ThemeVersion.
     * Maps template channel to theme channel (MAIL→MAIL, HTML→HTML; SMS has no theme wrapping).
     */
    private function wrapWithTheme(
        RenderedTemplate $rendered,
        Template $template,
        TemplateRenderInput $input,
    ): RenderedTemplate {
        $themeName = $template->getTheme();
        if ($themeName === null || $themeName === '') {
            return $rendered;
        }

        $themeChannel = match ($input->channel()) {
            TemplateChannelOptions::MAIL => ThemeVersionChannelOptions::MAIL,
            TemplateChannelOptions::HTML => ThemeVersionChannelOptions::HTML,
            default                      => null,
        };

        if ($themeChannel === null) {
            return $rendered;
        }

        $extraVars = [
            'title'   => $input->variables()['title'] ?? '',
            'subject' => $rendered->getSubject() ?? '',
        ];

        $wrapped = $this->themeRenderer->render(
            themeName: $themeName,
            channel: $themeChannel,
            innerContent: $rendered->htmlContent(),
            locale: $input->locale(),
            tenantRef: $input->tenant(),
            extraVars: $extraVars,
        );

        if ($wrapped === null) {
            return $rendered;
        }

        return new RenderedTemplate(
            htmlContent: $wrapped,
            subject: $rendered->getSubject(),
            textContent: $rendered->getTextContent(),
            assets: $rendered->assets(),
        );
    }
}
